#!/usr/bin/env python3
"""
Round 191o (culprits), 8 October 2026. Needs round 190o.

Earth's tipping points (Global Tipping Points Report 2025).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 191o (8 October)\n\nNeeds round 190o (guards on its heading). Tiles patch round191o_tiles.py\nbeside it. No app.js?v= bump.\n\n- tipping_points (route sitemap, tiles tipping/tipping_points.places.geojson\n  and .boxes.json, pictures in tiles tipping/img/), from the owner\'s PDF of\n  the Global Tipping Points Report 2025 (CC BY-SA 4.0; boxes shared alike).\n  Built once in the sandbox (no tiles script): section 2.2 read in column\n  order with PyMuPDF; Table 2.2.1, 2.4.1, 2.4.4, A2.2.1 and the risk\n  register (Figure 2.4.1) transcribed; Table 2.4.3 read cell by cell from\n  its colours. 21 systems placed as marks (placed by this map near the\n  middle of where Figure 2.2.1 draws them; disclosed in each box), 10\n  widespread systems in the entries window. 26 SREX regions (regionmask\'s\n  outlines) shaded by each of the 9 impact columns or the count of major or\n  worse; each region\'s box has its row, its continent\'s text (paragraphs\n  naming the region marked) and the report\'s continent map. Table 2.4.3\n  uses a red (224,102,102) its legend does not list; shown as "Red (no\n  legend entry)" between Major and Critical. Report colours redrawn in the\n  map\'s blues. Entries also hold "Do the IPCC\'s projections include tipping\n  points?" (AR6 WGI SPM C.3, C.3.2, C.3.4, B.5.3, B.4.3; the report pp.46,\n  92, 116, 127; Brysse et al. 2013, Kemp et al. 2022, Hansen et al. 2023,\n  Hausfather & Peters 2020, each checked). Filed under Climate > Tipping\n  points (first) and Oceans > Tipping points.\n- Tiles bii_nhm.py: the museum\'s zip holds another zip and a manifest; zips\n  inside zips are now opened (up to three deep) to find the GeoTIFF.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round191o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 190o" not in h.read_text(encoding="utf-8"):
        sys.exit("round191o: round 190o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round191o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round191o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round191o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
